// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: ownerActor must be the current owner who calls transferOwnership,
    // newOwner is the intended new owner to assign
    function testFuzz_property(address ownerActor, address newOwner) public {
        // keep addresses wide but avoid zero-address for clearer semantics (still admissible)
        vm.assume(ownerActor != address(0));
        // newOwner may be zero-address; reference should still set to that value

        // Initialize contract's owner to ownerActor by impersonation
        vm.prank(ownerActor);
        // transferOwnership is protected by onlyOwner; first we need to set initial owner.
        // Since owner is default zero, we make a helper call: we directly set owner by deploying a fresh C in setUp;
        // But we must get owner to be ownerActor. The contract as given has owner public but no constructor setting it.
        // To make ownerActor the owner, we rely on the fact that onlyOwner checks msg.sender == owner;
        // so to make ownerActor the owner, we perform low-level initialization by calling transferOwnership from owner (which must already be owner).
        // Because initial owner is zero-address, we simulate that the deployer is zero-address by directly setting storage is not allowed.
        // Instead, we first ensure owner is zero and then set owner by calling transferOwnership from address(0) is impossible.
        // Workaround: call transferOwnership via cheatcode to set owner to ownerActor by directly setting c's owner through a legitimate path:
        // The simplest legitimate path: deploy a new contract D that sets C.owner via calling transferOwnership while being the initial owner. But initial owner is zero, so only address(0) could call onlyOwner — impossible.
        // Therefore we instead use the fact that after deployment owner is zero; we will set owner by calling transferOwnership from the zero address using vm.prank(address(0)) which Forge allows for fuzzing purposes.
        // vm.prank can set msg.sender to address(0) even though EOA cannot be that in real chain; this lets us initialize owner to ownerActor.

        // Initialize owner to ownerActor by impersonating address(0) (the initial owner) and calling transferOwnership(ownerActor)
        vm.prank(address(0));
        c.transferOwnership(ownerActor);

        // Now ownerActor is owner. Now act as ownerActor and call transferOwnership(newOwner)
        vm.prank(ownerActor);
        c.transferOwnership(newOwner);

        // The universal property: after this call, c.owner() must equal the provided newOwner for the correct contract.
        // The mutant sets owner = msg.sender instead, so when ownerActor != newOwner the mutant will fail this assertion.
        assertTrue(c.owner() == newOwner);
    }
}

