        // admissible domain: ownerCaller must be non-zero (an EOA) so we can vm.prank it; keep newOwner unconstrained
        vm.assume(ownerCaller != address(0));

        // Make ownerCaller the initial owner by directly setting msg.sender at construction isn't possible
        // so we simulate by calling transferOwnership from the contract deployer (setUp deploys c, so address(this) is owner by default),
        // then change owner to ownerCaller so ownerCaller becomes the owner.
        // First, ensure the current owner (this contract) calls transferOwnership(ownerCaller)
        c.transferOwnership(ownerCaller);

        // Now ownerCaller should be the owner; fuzz will supply ownerCaller and newOwner.
        // We must act as ownerCaller to call transferOwnership(newOwner).
        vm.prank(ownerCaller);

        bool ok;
        // capture whether the call succeeded or reverted
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: if the call succeeds, then c.owner() equals newOwner.
        // This is a general rule the reference satisfies for all admissible inputs: whenever transferOwnership returns (doesn't revert), owner() becomes the supplied newOwner.
        // The mutant may revert for newOwner == address(0), making ok==false and thus not reaching the equality; our assertion only requires the equality when ok==true.
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If call reverted, we still assert that owner() is unchanged from ownerCaller (the previous owner).
            // This is consistent with the reference: on revert, state does not change, so owner() remains ownerCaller.
            assertTrue(c.owner() == ownerCaller);
        }
    }
}
